package com.crms.entity;import java.time.Instant;import org.springframework.data.annotation.Id;import org.springframework.data.mongodb.core.mapping.Document;@Document("notifications") public class Notification{@Id private Long id;private User user;private String title;private String message;private boolean readFlag=false;private Instant createdAt=Instant.now();public Long getId(){return id;}public void setId(Long v){id=v;}public User getUser(){return user;}public void setUser(User v){user=v;}public String getTitle(){return title;}public void setTitle(String v){title=v;}public String getMessage(){return message;}public void setMessage(String v){message=v;}public boolean isReadFlag(){return readFlag;}public void setReadFlag(boolean v){readFlag=v;}public Instant getCreatedAt(){return createdAt;}}
